using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class ReferenceActualChecks {
 public sealed class Document {public Video video;public DualCommentResult after;public CommentSuggestion best;}
 public static int Main(string[] args){try{string root=args[0];var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};var doc=json.Deserialize<Document>(File.ReadAllText(Path.Combine(root,"extension/data/replier-grounded-checks/whole-comment-final-CFYOk550ckc.json")));var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load(doc.video.Id);var pool=doc.after.Batches.Where(b=>b.Result!=null).SelectMany(b=>b.Result.Comments).ToArray();var rows=new[]{pool.First(r=>r.Text.Contains("아마존")),pool.First(r=>r.Text==doc.best.Text),pool.First(r=>r.Text=="벤틀리 스킨 디자인이 정말 예쁘네요!")};var before=rows.Select(r=>new{text=r.Text,score=r.FitScore,eligible=r.FitEligible}).ToArray();foreach(var row in rows)row.FitContextKey=null;
 var runtimes=DualCommentService.Models.ToDictionary(n=>n,n=>new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),n));try{new CombinedFitScoring(new FitScoring(runtimes[DualCommentService.Models[0]]),new FitScoring(runtimes[DualCommentService.Models[1]]),runtimes[DualCommentService.Models[0]].Unload).Evaluate(doc.video,content,rows,CancellationToken.None).GetAwaiter().GetResult();}finally{foreach(var runtime in runtimes.Values.Reverse())runtime.Dispose();}
 bool[] expected={false,true,true};bool passed=true;for(int i=0;i<rows.Length;i++){passed&=rows[i].FitEligible==expected[i];Console.WriteLine("RESULT "+rows[i].FitEligible+" score="+rows[i].FitScore+" "+rows[i].Text);Console.WriteLine(rows[i].FitReason);}
 File.WriteAllText(Path.Combine(root,"extension/data/replier-grounded-checks/reference-grounding-CFYOk550ckc.json"),json.Serialize(new{video=doc.video,before=before,after=rows,expected=expected,pass=passed,reused_existing_candidates=true}));Console.WriteLine(passed?"PASS missing name excluded; original reactions and verified names retained":"FAIL reviewed reference contrast mismatch");return passed?0:1;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
